/*
 * A055880  Quotients arising from sequence A053317.
 * https://oeis.org/A055880
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = A053317(n) / 2^n A053317(n) is the smallest integer
 *            composed only of the digits 2 and 5 that is divisible by 2^n.
 *            The quotient a(n) can be generated by the recurrence a(1) = 1 if
 *            a(n-1) is odd : a(n) = (5^n + a(n-1)) / 2 if a(n-1) is even :
 *            a(n) = 5^(n-1) + a(n-1) / 2
 * Range:     u8 n <= 3, u16 n <= 6, u32 n <= 13, u64 n <= 28, u128 n <= 55,
 *            big any n
 * Helpers:   ensure_cache
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include "../utils/ensure_cache.h"

static seq_t *cache     = NULL;   /* cache[n-1] holds a(n) */
static size_t cache_cap = 0;      /* current allocated capacity */
static idx_t  max_n     = 0;      /* highest n already computed (>=1) */
static seq_t  pow5_cur  = (seq_t)5; /* 5^max_n;  for max_n==0 value is unused */

/* compute a(n) for n >= 1 */
seq_t a(idx_t n)
{
    if (n <= 0) return (seq_t)0;   /* not used in practice */

    /* initialise cache if empty */
    if (cache == NULL) {
        /* allocate space for at least one element */
        ensure_cache(1, &cache, &cache_cap);
        cache[0] = (seq_t)1;     /* a(1) = 1 */
        pow5_cur = (seq_t)5;     /* 5^1 */
        max_n    = 1;
    }

    /* extend cache if necessary */
    if (n > max_n) {
        /* make sure there is enough storage */
        ensure_cache(n, &cache, &cache_cap);

        seq_t prev_a   = cache[max_n - 1];   /* a(max_n)   */
        seq_t prev_pow = pow5_cur;           /* 5^max_n    */

        for (idx_t i = max_n + 1; i <= n; ++i) {
            seq_t next_pow = prev_pow * (seq_t)5;   /* 5^i          */

            seq_t next_a;
            if ((prev_a & (seq_t)1) != 0) {        /* prev_a odd   */
                next_a = (next_pow + prev_a) / (seq_t)2;
            } else {                               /* prev_a even  */
                next_a = prev_pow + (prev_a / (seq_t)2);
            }

            cache[i - 1] = next_a;    /* store a(i)     */
            prev_a      = next_a;     /* update for loop */
            prev_pow    = next_pow;
        }

        pow5_cur = prev_pow;   /* now 5^n          */
        max_n    = n;          /* updated limit     */
    }

    return cache[n - 1];
}
